IF "DB1007_Alarm".MCP_Alarm_all = FALSE THEN
    FOR #number := 1 TO 256 BY 1 DO
        IF "IDB1046_PN_DEV_DIAG".PNDeviceData.Basic[#number].DeviceState_BitCoded.Configured AND NOT"IDB1046_PN_DEV_DIAG".PNDeviceData.Basic[#number].DeviceState_BitCoded.Present THEN
            "DB1007_Alarm".PN_Net[#number] := FALSE;
        ELSE
            "DB1007_Alarm".PN_Net[#number] := TRUE;
        END_IF;
    END_FOR;
END_IF;*0)
